def check_solution(x, y, z):
    """Checks if the triple (x, y, z) satisfies the equation."""
    return x**3 + y**3 + z**3 - x**2 * y**2 * z**2 == 0

solutions = []
print("Starting search...")

# Iterate over x up to 2
for x in range(1, 3):
    # Iterate over y such that x <= y
    # Since z goes up to 10, y must also be at most 10.
    for y in range(x, 11):
        # Iterate over z such that y <= z and z <= 10
        for z in range(y, 11):
            if check_solution(x, y, z):
                solutions.append((x, y, z))

if solutions:
    print("\nSolutions found:")
    for sol in solutions:
        print(sol)
else:
    print("\nNo solutions found within the given bounds.")

print("\nTotal solutions found:", len(solutions))

